      [/(shoulder press|жим гантелей над головою|machine shoulder press|жим плечима в тренажері|lateral raise|підйом гантелей у сторони)/i,6],
      [/(biceps curl|згинання рук|triceps|розгинання рук|plank|планка|dead bug|bird dog)/i,4]
