      if(equipment==='gym'&&/(barbell|штанг|machine|тренажер|cable|блок)/i.test(n))sc+=4;
      if(equipment==='dumbbells'&&/(dumbbell|гантел|floor press|гоблет|goblet)/i.test(n))sc+=5;
