      panel=`<div class="th-program-grid">${cards.map(c=>`<button class="th-program ${selectedProgram===c[0]?'active':''}" onclick="gtSelectTrainingProgram('${c[0]}')"><strong>${c[1]}</strong><span>${c[2]} · ${selectedProgram===c[0]?tr('Активна','Active'):c[3]}</span></button>`).join('')}</div><div class="th-feature-card"><span class="th-kicker">${activeBadge}</span><h2>${info[lang==='en'?'en':'uk']}</h2><p class="th-description">${info[lang==='en'?'enDesc':'ukDesc']}</p><p class="th-note">${info[lang==='en'?'enWhy':'ukWhy']}</p>${goalNote}</div><div class="th-day-list">${daysHtml}</div><button class="th-start-day" style="margin-top:18px" onclick="gtStartHubDay(0)">${tr('Почати рекомендоване тренування','Start recommended workout')} →</button>`;
